INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('707e5740-5d6b-560d-badb-da578d370f5d', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Familio FA144', 'PL', 118.08, 88.7, 'Dom drewniany dla rodziny: cztery sypialnie, salon, kuchnia, dwie łazienki, garderoba i pomieszczenie gospodarcze na ok. 118 m² powierzchni użytkowej (145 m² po podłodze), w dwóch kondygnacjach o powierzchni zabudowy 88,7 m² (11,2 × 7,92 m). Dwuspadowy dach pod kątem 40° i prostokątna bryła. Elewacja FA144: jasna deska elewacyjna wykończona panelami na rąbek stojący. W cenie zimna płyta fundamentowa.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 5, 4, 2, 2, '11,2 × 7,92 m', 'Dwuspadowy, nachylenie 40°, wysokość do kalenicy 7,5 m; pokrycie: panel na rąbek stojący lub blachodachówka', 'Szkielet drewniany z drewna konstrukcyjnego klasy C24 (słupy 45 × 145 mm), ściany ocieplone wełną mineralną 150 + 50 mm, dach 200 + 50 mm', 'W cenie zimna płyta fundamentowa. Dopłata do płyty fundamentowej w pełni izolowanej (U = 0,180 W/(m²·K)); podłoga na fundamencie punktowym ma U = 0,184 W/(m²·K).', 'Dopłaty za gruntowanie i malowanie elewacji, schody zabiegowe, zadaszenie wejścia, płytę fundamentową w pełni izolowaną i każde dodatkowe okno połaciowe. Dopłata do ram okiennych w innym kolorze.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:14.863Z'::timestamptz, '2026-10-09T07:04:42.777Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna: ściany 150 + 50 mm, dach 200 + 50 mm (Uc = 0,148 W/(m²·K)), strop 150 mm, podłoga 150 mm; płyta fundamentowa z EPS grafitowym 50 mm i XPS 100 mm (Uc = 0,180 W/(m²·K)) lub podłoga na stopach (Uc = 0,184 W/(m²·K)).","ventilation":"grawitacyjna","wallBuildUp":"Deska elewacyjna 20 mm na wentylowanej szczelinie (łaty 25 × 40 mm), membrana wiatroizolacyjna, płyta MFP 12 mm, wełna mineralna 150 mm λ = 0,033 W/(mK), konstrukcja słupowa C24 45 × 145 mm, membrana paroszczelna, wełna mineralna 50 mm w ruszcie instalacyjnym 40 × 60 mm, wykończenie deską boazeryjną lub płytą G-K Riduro. Współczynnik przenikania ciepła ściany Uc = 0,195 W/(m²·K).","windowClass":"Stolarka okienna trzyszybowa w kolorze białym; stalowe drzwi zewnętrzne w kolorze grafitowym.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Zakres prac obejmuje montaż domu, położenie zimnej płyty fundamentowej, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.', NULL, NULL, NULL, '[{"id":"familio-fa144-room-1","name":"Wiatrołap","areaM2":3.42,"floorLevel":"parter"},{"id":"familio-fa144-room-2","name":"Korytarz","areaM2":8.46,"floorLevel":"parter"},{"id":"familio-fa144-room-3","name":"Pokój","areaM2":11.2,"floorLevel":"parter"},{"id":"familio-fa144-room-4","name":"Garderoba","areaM2":2.78,"floorLevel":"parter"},{"id":"familio-fa144-room-5","name":"Pokój","areaM2":10.16,"floorLevel":"parter"},{"id":"familio-fa144-room-6","name":"Łazienka","areaM2":5.82,"floorLevel":"parter"},{"id":"familio-fa144-room-7","name":"Pomieszczenie gospodarcze","areaM2":2.25,"floorLevel":"parter"},{"id":"familio-fa144-room-8","name":"Salon","areaM2":21.28,"floorLevel":"parter"},{"id":"familio-fa144-room-9","name":"Kuchnia","areaM2":7.68,"floorLevel":"parter"},{"id":"familio-fa144-room-10","name":"Korytarz","areaM2":5.5,"floorLevel":"pietro"},{"id":"familio-fa144-room-11","name":"Pokój","areaM2":15.2,"floorLevel":"pietro"},{"id":"familio-fa144-room-12","name":"Łazienka","areaM2":5.83,"floorLevel":"pietro"},{"id":"familio-fa144-room-13","name":"Pokój","areaM2":18.5,"floorLevel":"pietro"}]'::jsonb, '[{"id":"familio-fa144-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"familio-fa144-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"familio-fa144-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"familio-fa144-faq-4","answer":"W standardzie z wykończeniem wnętrz ściany i strop są wykończone deską boazeryjną lub płytą G-K, a podłoga ma suchy jastrych, więc nie trzeba ich wykańczać. W stanie surowym zamkniętym (SSZ) tych prac nie ma w cenie.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"familio-fa144-faq-5","answer":"Tak, za dopłatą. Producent podaje jej wysokość w indywidualnej wycenie.","question":"Czy ramy okienne mogą mieć inny kolor?"},{"id":"familio-fa144-faq-6","answer":"Zakres prac obejmuje montaż domu, położenie zimnej płyty fundamentowej, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"familio-fa144-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"familio-fa144-req-2","key":"miejsce-dla-dzwigu","label":"Miejsce dla dźwigu","custom":false},{"id":"familio-fa144-req-3","key":"formalnosci","label":"Formalności","custom":false}]'::jsonb, NULL, 'logbar-familio-fa144') ON CONFLICT DO NOTHING;
INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('171a46b4-28b2-5e29-b7fb-e038c522c006', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Bingo Piętrowy Perfeco A', 'PL', 82.09, 69.9, 'Dwukondygnacyjny dom całoroczny o powierzchni zabudowy 69,9 m² (11,39 × 6,11 m), z konstrukcją w całości z drewna konstrukcyjnego klasy C24. Cztery pokoje, dwie łazienki i salon z aneksem kuchennym na ok. 82 m² powierzchni użytkowej (103 m² po podłodze). Dwuspadowy dach pod kątem 40° i prosta bryła sprawiają, że dom odnajdzie się na większości działek. Elewacja A: jasna deska elewacyjna w kolorze drewna. Do wyboru cztery układy wnętrz (podstawowy i wersje 1–3) oraz stan surowy zamknięty lub standard z wykończeniem wnętrz.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 5, 4, 2, 2, '11,39 × 6,11 m', 'Dwuspadowy, nachylenie 40°, wysokość do kalenicy 6,46 m; pokrycie: panel na rąbek stojący lub blachodachówka', 'Szkielet drewniany z drewna konstrukcyjnego klasy C24 (słupy 45 × 145 mm), ściany ocieplone wełną mineralną 150 + 50 mm, dach 200 + 50 mm', 'W cenie stopy fundamentowe (podłoga na fundamencie punktowym, U = 0,184 W/(m²·K)). Opcjonalnie płyta fundamentowa w pełni izolowana (U = 0,180 W/(m²·K)) lub płyta przy posadzce betonowej po stronie inwestora.', 'Cztery układy wnętrz (podstawowy i wersje 1–3), dopłaty za zadaszenie wejścia, schody zabiegowe, płytę fundamentową, rekuperację i wykończenie elewacji. Dopłata do ram okiennych w innym kolorze.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:11.468Z'::timestamptz, '2026-10-09T07:04:40.013Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna: ściany 150 + 50 mm, dach 200 + 50 mm (Uc = 0,148 W/(m²·K)), strop 150 mm, podłoga 150 mm; płyta fundamentowa z EPS grafitowym 50 mm i XPS 100 mm (Uc = 0,180 W/(m²·K)) lub podłoga na stopach (Uc = 0,184 W/(m²·K)).","ventilation":"grawitacyjna","wallBuildUp":"Deska elewacyjna 20 mm na wentylowanej szczelinie (łaty 25 × 40 mm), membrana wiatroizolacyjna, płyta MFP 12 mm, wełna mineralna 150 mm λ = 0,033 W/(mK), konstrukcja słupowa C24 45 × 145 mm, membrana paroszczelna, wełna mineralna 50 mm w ruszcie instalacyjnym 40 × 60 mm, wykończenie deską boazeryjną lub płytą G-K Riduro. Współczynnik przenikania ciepła ściany Uc = 0,195 W/(m²·K).","windowClass":"Stolarka okienna trzyszybowa w kolorze białym; stalowe drzwi zewnętrzne w kolorze grafitowym.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.', NULL, NULL, NULL, '[{"id":"bingo-a-room-1","name":"Wiatrołap","areaM2":2.4,"floorLevel":"parter"},{"id":"bingo-a-room-2","name":"Korytarz","areaM2":7.19,"floorLevel":"parter"},{"id":"bingo-a-room-3","name":"Pokój","areaM2":9.64,"floorLevel":"parter"},{"id":"bingo-a-room-4","name":"Pokój","areaM2":9.59,"floorLevel":"parter"},{"id":"bingo-a-room-5","name":"Łazienka","areaM2":3.48,"floorLevel":"parter"},{"id":"bingo-a-room-6","name":"Pomieszczenie gospodarcze","areaM2":1.25,"floorLevel":"parter"},{"id":"bingo-a-room-7","name":"Salon z aneksem kuchennym","areaM2":22.49,"floorLevel":"parter"},{"id":"bingo-a-room-8","name":"Korytarz","areaM2":3.02,"floorLevel":"pietro"},{"id":"bingo-a-room-9","name":"Pokój","areaM2":9.11,"floorLevel":"pietro"},{"id":"bingo-a-room-10","name":"Łazienka","areaM2":3.22,"floorLevel":"pietro"},{"id":"bingo-a-room-11","name":"Pokój","areaM2":11.7,"floorLevel":"pietro"}]'::jsonb, '[{"id":"bingo-a-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"bingo-a-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"bingo-a-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"bingo-a-faq-4","answer":"W standardzie z wykończeniem wnętrz ściany i strop są wykończone deską boazeryjną lub płytą G-K, a podłoga ma suchy jastrych, więc nie trzeba ich wykańczać. W stanie surowym zamkniętym (SSZ) tych prac nie ma w cenie.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"bingo-a-faq-5","answer":"Wersja podstawowa ma cztery pokoje i dwie łazienki. Wersja 1 dodaje okno 180 × 220 cm na parterze (+5 200 zł netto). Wersja 2 daje trzy sypialnie na poddaszu, garderobę i pomieszczenie gospodarcze na parterze oraz wyższą ściankę kolankową (+40 700 zł netto). Wersja 3 poszerza salon i rezygnuje z pomieszczenia gospodarczego (+4 300 zł netto).","question":"Czym różnią się wersje układu wnętrz?"},{"id":"bingo-a-faq-6","answer":"Tak, za dopłatą. Producent podaje jej wysokość w indywidualnej wycenie.","question":"Czy ramy okienne mogą mieć inny kolor?"},{"id":"bingo-a-faq-7","answer":"Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"bingo-a-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"bingo-a-req-2","key":"miejsce-dla-dzwigu","label":"Miejsce dla dźwigu","custom":false},{"id":"bingo-a-req-3","key":"formalnosci","label":"Formalności","custom":false}]'::jsonb, NULL, 'logbar-bingo-pietrowy-perfeco-a') ON CONFLICT DO NOTHING;
