INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('d34dbf16-c73e-5b8a-9a90-c776be9713bf', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Familio FD144', 'PL', 118.08, 88.7, 'Dom drewniany dla rodziny: cztery sypialnie, salon, kuchnia, dwie łazienki, garderoba i pomieszczenie gospodarcze na ok. 118 m² powierzchni użytkowej (145 m² po podłodze), w dwóch kondygnacjach o powierzchni zabudowy 88,7 m² (11,2 × 7,92 m). Dwuspadowy dach pod kątem 40° i prostokątna bryła. Elewacja FD144: jasna deska elewacyjna z elementami paneli na rąbek stojący zachodzącymi na boczną elewację i na szczyty piętra. W cenie zimna płyta fundamentowa.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 5, 4, 2, 2, '11,2 × 7,92 m', 'Dwuspadowy, nachylenie 40°, wysokość do kalenicy 7,5 m; pokrycie: panel na rąbek stojący lub blachodachówka', 'Szkielet drewniany z drewna konstrukcyjnego klasy C24 (słupy 45 × 145 mm), ściany ocieplone wełną mineralną 150 + 50 mm, dach 200 + 50 mm', 'W cenie zimna płyta fundamentowa. Dopłata do płyty fundamentowej w pełni izolowanej (U = 0,180 W/(m²·K)); podłoga na fundamencie punktowym ma U = 0,184 W/(m²·K).', 'Dopłaty za gruntowanie i malowanie elewacji, schody zabiegowe, zadaszenie wejścia, płytę fundamentową w pełni izolowaną i każde dodatkowe okno połaciowe. Dopłata do ram okiennych w innym kolorze.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:14.628Z'::timestamptz, '2026-10-09T07:04:42.539Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna: ściany 150 + 50 mm, dach 200 + 50 mm (Uc = 0,148 W/(m²·K)), strop 150 mm, podłoga 150 mm; płyta fundamentowa z EPS grafitowym 50 mm i XPS 100 mm (Uc = 0,180 W/(m²·K)) lub podłoga na stopach (Uc = 0,184 W/(m²·K)).","ventilation":"grawitacyjna","wallBuildUp":"Deska elewacyjna 20 mm na wentylowanej szczelinie (łaty 25 × 40 mm), membrana wiatroizolacyjna, płyta MFP 12 mm, wełna mineralna 150 mm λ = 0,033 W/(mK), konstrukcja słupowa C24 45 × 145 mm, membrana paroszczelna, wełna mineralna 50 mm w ruszcie instalacyjnym 40 × 60 mm, wykończenie deską boazeryjną lub płytą G-K Riduro. Współczynnik przenikania ciepła ściany Uc = 0,195 W/(m²·K).","windowClass":"Stolarka okienna trzyszybowa w kolorze białym; stalowe drzwi zewnętrzne w kolorze grafitowym.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Zakres prac obejmuje montaż domu, położenie zimnej płyty fundamentowej, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.', NULL, NULL, NULL, '[{"id":"familio-fd144-room-1","name":"Wiatrołap","areaM2":3.42,"floorLevel":"parter"},{"id":"familio-fd144-room-2","name":"Korytarz","areaM2":8.46,"floorLevel":"parter"},{"id":"familio-fd144-room-3","name":"Pokój","areaM2":11.2,"floorLevel":"parter"},{"id":"familio-fd144-room-4","name":"Garderoba","areaM2":2.78,"floorLevel":"parter"},{"id":"familio-fd144-room-5","name":"Pokój","areaM2":10.16,"floorLevel":"parter"},{"id":"familio-fd144-room-6","name":"Łazienka","areaM2":5.82,"floorLevel":"parter"},{"id":"familio-fd144-room-7","name":"Pomieszczenie gospodarcze","areaM2":2.25,"floorLevel":"parter"},{"id":"familio-fd144-room-8","name":"Salon","areaM2":21.28,"floorLevel":"parter"},{"id":"familio-fd144-room-9","name":"Kuchnia","areaM2":7.68,"floorLevel":"parter"},{"id":"familio-fd144-room-10","name":"Korytarz","areaM2":5.5,"floorLevel":"pietro"},{"id":"familio-fd144-room-11","name":"Pokój","areaM2":15.2,"floorLevel":"pietro"},{"id":"familio-fd144-room-12","name":"Łazienka","areaM2":5.83,"floorLevel":"pietro"},{"id":"familio-fd144-room-13","name":"Pokój","areaM2":18.5,"floorLevel":"pietro"}]'::jsonb, '[{"id":"familio-fd144-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"familio-fd144-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"familio-fd144-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"familio-fd144-faq-4","answer":"W standardzie z wykończeniem wnętrz ściany i strop są wykończone deską boazeryjną lub płytą G-K, a podłoga ma suchy jastrych, więc nie trzeba ich wykańczać. W stanie surowym zamkniętym (SSZ) tych prac nie ma w cenie.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"familio-fd144-faq-5","answer":"Tak, za dopłatą. Producent podaje jej wysokość w indywidualnej wycenie.","question":"Czy ramy okienne mogą mieć inny kolor?"},{"id":"familio-fd144-faq-6","answer":"Zakres prac obejmuje montaż domu, położenie zimnej płyty fundamentowej, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"familio-fd144-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"familio-fd144-req-2","key":"miejsce-dla-dzwigu","label":"Miejsce dla dźwigu","custom":false},{"id":"familio-fd144-req-3","key":"formalnosci","label":"Formalności","custom":false}]'::jsonb, NULL, 'logbar-familio-fd144') ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('261113fb-105d-4b3d-9ae6-71926b3aa2cf', '171a46b4-28b2-5e29-b7fb-e038c522c006', 'en', 'Logbar Bingo Piętrowy Perfeco A', 'Two-storey year-round house with a footprint of 69.9 m² (11.39 × 6.11 m), built entirely from C24 structural timber. Four rooms, two bathrooms and a living room with a kitchenette on about 82 m² of usable floor area (103 m² measured at floor level). The gable roof at 40° and the simple volume suit most plots. Façade A: light cladding boards in a natural wood colour. Four interior layouts (base and versions 1–3) are available, in a closed-shell or finished-interior standard.', '2026-10-09T06:28:11.468Z'::timestamptz, '2026-10-09T07:04:50.568Z'::timestamptz, '[{"id":"bingo-a-room-1","name":"Entrance vestibule"},{"id":"bingo-a-room-2","name":"Hallway"},{"id":"bingo-a-room-3","name":"Room"},{"id":"bingo-a-room-4","name":"Room"},{"id":"bingo-a-room-5","name":"Bathroom"},{"id":"bingo-a-room-6","name":"Utility room"},{"id":"bingo-a-room-7","name":"Living room with kitchenette"},{"id":"bingo-a-room-8","name":"Hallway"},{"id":"bingo-a-room-9","name":"Room"},{"id":"bingo-a-room-10","name":"Bathroom"},{"id":"bingo-a-room-11","name":"Room"}]'::jsonb, '[{"id":"bingo-a-faq-1","answer":"No. The cost of transport and of a crane at the assembly site must be added to the price. The architectural and building design is not included.","question":"Does the price include transport, a crane and the building design?"},{"id":"bingo-a-faq-2","answer":"Yes, all prices in the producer''s offer are net prices. The VAT rate depends on the intended use of the building.","question":"Are the prices net prices?"},{"id":"bingo-a-faq-3","answer":"The producer gives a 24-month warranty on the whole house and a 10-year warranty on the structure.","question":"What is the warranty?"},{"id":"bingo-a-faq-4","answer":"In the finished-interior standard the walls and ceiling are finished with tongue-and-groove boards or plasterboard and the floor has a dry screed, so they need no further finishing. In the closed-shell state (SSZ) this work is not included in the price.","question":"Do the interiors need finishing after assembly?"},{"id":"bingo-a-faq-5","answer":"The base version has four rooms and two bathrooms. Version 1 adds a 180 × 220 cm window on the ground floor (+PLN 5,200 net). Version 2 gives three bedrooms upstairs, a walk-in wardrobe and a utility room downstairs and a higher knee wall (+PLN 40,700 net). Version 3 widens the living room and drops the utility room (+PLN 4,300 net).","question":"How do the interior layout versions differ?"},{"id":"bingo-a-faq-6","answer":"Yes, for a surcharge. The producer states its amount in an individual quotation.","question":"Can the window frames have a different colour?"},{"id":"bingo-a-faq-7","answer":"The scope of work includes assembling the house, installing the foundation pads, insulating the external walls, floor and roof, laying standing-seam roof panels or metal roof tiles, guttering, installing the windows and external doors, running the electrical and water and sewage installations, and finishing the façade.","question":"What does the producer''s scope of work cover?"}]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'Foundation pads are included in the price (floor on a point foundation, U = 0.184 W/(m²·K)). A fully insulated foundation slab (U = 0.180 W/(m²·K)) or a slab with a concrete floor provided by the investor is optional.', NULL, 'Timber frame of C24 structural timber (45 × 145 mm studs), walls insulated with 150 + 50 mm mineral wool, roof 200 + 50 mm', 'Gable roof, 40° pitch, ridge height 6.46 m; covering: standing-seam panels or metal roof tiles', 'Four interior layouts (base and versions 1–3), surcharges for an entrance canopy, winder stairs, a foundation slab, heat recovery ventilation and façade finishing. Surcharge for window frames in a different colour.', 'The scope of work includes assembling the house, installing the foundation pads, insulating the external walls, floor and roof, laying standing-seam roof panels or metal roof tiles, guttering, installing the windows and external doors, running the electrical and water and sewage installations, and finishing the façade.') ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('76e16d61-51a0-42e3-9d74-984869762f80', '194d8a47-6317-558d-9d45-9a1b8ee8b505', 'nl', 'Logbar Bingo Piętrowy Perfeco B', 'Huis met twee bouwlagen voor het hele jaar, met een bebouwde oppervlakte van 69,9 m² (11,39 × 6,11 m), volledig gebouwd van constructiehout klasse C24. Vier kamers, twee badkamers en een woonkamer met keukenhoek op circa 82 m² bruikbare vloeroppervlakte (103 m² gemeten op vloerniveau). Het zadeldak van 40° en het eenvoudige volume passen op de meeste kavels. Gevel B: planken verkoold volgens de Shou Sugi Ban-methode. Er zijn vier indelingen beschikbaar (basis en versies 1–3), naar keuze casco dicht of de afbouwstandaard met afgewerkt interieur.', '2026-10-09T06:28:11.984Z'::timestamptz, '2026-10-09T07:04:50.844Z'::timestamptz, '[{"id":"bingo-b-room-1","name":"Portaal"},{"id":"bingo-b-room-2","name":"Gang"},{"id":"bingo-b-room-3","name":"Kamer"},{"id":"bingo-b-room-4","name":"Kamer"},{"id":"bingo-b-room-5","name":"Badkamer"},{"id":"bingo-b-room-6","name":"Bijkeuken"},{"id":"bingo-b-room-7","name":"Woonkamer met keukenhoek"},{"id":"bingo-b-room-8","name":"Gang"},{"id":"bingo-b-room-9","name":"Kamer"},{"id":"bingo-b-room-10","name":"Badkamer"},{"id":"bingo-b-room-11","name":"Kamer"}]'::jsonb, '[{"id":"bingo-b-faq-1","answer":"Nee. De kosten van transport en van een kraan op de montagelocatie komen bovenop de prijs. Het architectonisch en bouwkundig ontwerp is niet inbegrepen.","question":"Zijn transport, een kraan en het bouwkundig ontwerp bij de prijs inbegrepen?"},{"id":"bingo-b-faq-2","answer":"Ja, alle prijzen in het aanbod van de producent zijn nettoprijzen. Het btw-tarief hangt af van de bestemming van het gebouw.","question":"Zijn de genoemde prijzen nettoprijzen?"},{"id":"bingo-b-faq-3","answer":"De producent geeft 24 maanden garantie op het hele huis en 10 jaar op de constructie.","question":"Welke garantie geldt er?"},{"id":"bingo-b-faq-4","answer":"Bij de afbouwstandaard zijn wanden en plafond afgewerkt met profielplanken of gipsplaten en heeft de vloer een droge dekvloer, zodat verdere afwerking niet nodig is. Bij casco dicht (SSZ) zijn deze werkzaamheden niet in de prijs inbegrepen.","question":"Moet het interieur na de montage nog worden afgewerkt?"},{"id":"bingo-b-faq-5","answer":"De basisversie heeft vier kamers en twee badkamers. Versie 1 voegt een raam van 180 × 220 cm op de begane grond toe (+5.200 PLN netto). Versie 2 geeft drie slaapkamers boven, een inloopkast en een bijkeuken beneden en een hogere knieschot (+40.700 PLN netto). Versie 3 vergroot de woonkamer en laat de bijkeuken vervallen (+4.300 PLN netto).","question":"Hoe verschillen de versies van de indeling?"},{"id":"bingo-b-faq-6","answer":"Ja, tegen toeslag. De producent noemt het bedrag in een individuele offerte.","question":"Kunnen de raamkozijnen een andere kleur hebben?"},{"id":"bingo-b-faq-7","answer":"Het werkpakket omvat de montage van het huis, de montage van de funderingspoeren, de thermische isolatie van buitenwanden, vloer en dak, het leggen van liggende-felspanelen of metalen dakpannen, de dakgoten, de montage van ramen en buitendeuren, het aanleggen van de elektrische en de water- en rioolinstallatie en de uitvoering van de gevel.","question":"Wat omvat het werkpakket van de producent?"}]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'Funderingspoeren zijn bij de prijs inbegrepen (vloer op puntfundering, U = 0,184 W/(m²·K)). Optioneel is een volledig geïsoleerde funderingsplaat (U = 0,180 W/(m²·K)) of een plaat met betonvloer door de opdrachtgever.', NULL, 'Houtskelet van constructiehout klasse C24 (stijlen 45 × 145 mm), wanden geïsoleerd met 150 + 50 mm minerale wol, dak 200 + 50 mm', 'Zadeldak, 40° helling, nokhoogte 6,46 m; dekking: liggende-felspanelen of metalen dakpannen', 'Vier indelingen (basis en versies 1–3), toeslagen voor een overkapping van de ingang, een trap met kwartslagen, een funderingsplaat, warmteterugwinning en gevelafwerking. Toeslag voor raamkozijnen in een andere kleur.', 'Het werkpakket omvat de montage van het huis, de montage van de funderingspoeren, de thermische isolatie van buitenwanden, vloer en dak, het leggen van liggende-felspanelen of metalen dakpannen, de dakgoten, de montage van ramen en buitendeuren, het aanleggen van de elektrische en de water- en rioolinstallatie en de uitvoering van de gevel.') ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('56343e2b-0f7a-499a-a023-74cb617e0ca3', 'd34dbf16-c73e-5b8a-9a90-c776be9713bf', 'en', 'Logbar Familio FD144', 'Timber family house: four bedrooms, a living room, a kitchen, two bathrooms, a walk-in wardrobe and a utility room on about 118 m² of usable floor area (145 m² measured at floor level), on two storeys with a footprint of 88.7 m² (11.2 × 7.92 m). Gable roof at 40° and a rectangular volume. Façade FD144: light cladding boards with standing-seam panel elements wrapping onto the side façade and the upper-floor gables. An uninsulated foundation slab is included in the price.', '2026-10-09T06:28:14.628Z'::timestamptz, '2026-10-09T07:04:53.111Z'::timestamptz, '[{"id":"familio-fd144-room-1","name":"Entrance vestibule"},{"id":"familio-fd144-room-2","name":"Hallway"},{"id":"familio-fd144-room-3","name":"Room"},{"id":"familio-fd144-room-4","name":"Walk-in wardrobe"},{"id":"familio-fd144-room-5","name":"Room"},{"id":"familio-fd144-room-6","name":"Bathroom"},{"id":"familio-fd144-room-7","name":"Utility room"},{"id":"familio-fd144-room-8","name":"Living room"},{"id":"familio-fd144-room-9","name":"Kitchen"},{"id":"familio-fd144-room-10","name":"Hallway"},{"id":"familio-fd144-room-11","name":"Room"},{"id":"familio-fd144-room-12","name":"Bathroom"},{"id":"familio-fd144-room-13","name":"Room"}]'::jsonb, '[{"id":"familio-fd144-faq-1","answer":"No. The cost of transport and of a crane at the assembly site must be added to the price. The architectural and building design is not included.","question":"Does the price include transport, a crane and the building design?"},{"id":"familio-fd144-faq-2","answer":"Yes, all prices in the producer''s offer are net prices. The VAT rate depends on the intended use of the building.","question":"Are the prices net prices?"},{"id":"familio-fd144-faq-3","answer":"The producer gives a 24-month warranty on the whole house and a 10-year warranty on the structure.","question":"What is the warranty?"},{"id":"familio-fd144-faq-4","answer":"In the finished-interior standard the walls and ceiling are finished with tongue-and-groove boards or plasterboard and the floor has a dry screed, so they need no further finishing. In the closed-shell state (SSZ) this work is not included in the price.","question":"Do the interiors need finishing after assembly?"},{"id":"familio-fd144-faq-5","answer":"Yes, for a surcharge. The producer states its amount in an individual quotation.","question":"Can the window frames have a different colour?"},{"id":"familio-fd144-faq-6","answer":"The scope of work includes assembling the house, laying the uninsulated foundation slab, insulating the external walls, floor and roof, laying standing-seam roof panels or metal roof tiles, guttering, installing the windows and external doors, running the electrical and water and sewage installations, and finishing the façade.","question":"What does the producer''s scope of work cover?"}]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'An uninsulated foundation slab is included in the price. A surcharge applies for a fully insulated slab (U = 0.180 W/(m²·K)); a floor on a point foundation has U = 0.184 W/(m²·K).', NULL, 'Timber frame of C24 structural timber (45 × 145 mm studs), walls insulated with 150 + 50 mm mineral wool, roof 200 + 50 mm', 'Gable roof, 40° pitch, ridge height 7.5 m; covering: standing-seam panels or metal roof tiles', 'Surcharges for priming and painting the façade, winder stairs, an entrance canopy, a fully insulated foundation slab and each additional roof window. Surcharge for window frames in a different colour.', 'The scope of work includes assembling the house, laying the uninsulated foundation slab, insulating the external walls, floor and roof, laying standing-seam roof panels or metal roof tiles, guttering, installing the windows and external doors, running the electrical and water and sewage installations, and finishing the façade.') ON CONFLICT DO NOTHING;
